mapper.update:
update popular_ranking
set book_title = #{bookTitle},
    monthly_borrow_times = #{monthlyBorrowTimes},
    total_borrow_times = #{totalBorrowTimes},
    statistics_month = #{statisticsMonth}
where id = #{id}

mapper.select:
select * from popular_ranking
and (book_title like concat('%', #{keyword}, '%') or statistics_month like concat('%', #{keyword}, '%'))
order by id desc limit #{limit} offset #{offset}
